CREATE TABLE IF NOT EXISTS hai_terminology_resource (scope_id text NOT NULL, resource_type text NOT NULL, resource_id text NOT NULL, canonical_url text NOT NULL, version text NOT NULL DEFAULT '', status text NOT NULL DEFAULT '', resource_json jsonb NOT NULL, content_mode text NOT NULL DEFAULT '', source_module text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(scope_id,resource_type,canonical_url,version));
CREATE TABLE IF NOT EXISTS hai_terminology_concept (scope_id text NOT NULL, system_url text NOT NULL, system_version text NOT NULL DEFAULT '', code text NOT NULL, display text NOT NULL DEFAULT '', definition text NOT NULL DEFAULT '', active boolean NOT NULL DEFAULT true, abstract boolean NOT NULL DEFAULT false, parent_code text NOT NULL DEFAULT '', properties_json jsonb, designations_json jsonb, PRIMARY KEY(scope_id,system_url,system_version,code));
CREATE TABLE IF NOT EXISTS hai_terminology_valueset (scope_id text NOT NULL, canonical_url text NOT NULL, version text NOT NULL DEFAULT '', status text NOT NULL DEFAULT '', compose_json jsonb NOT NULL DEFAULT '{}'::jsonb, expansion_json jsonb, expansion_timestamp timestamptz, expansion_fingerprint text NOT NULL DEFAULT '', PRIMARY KEY(scope_id,canonical_url,version));
CREATE TABLE IF NOT EXISTS hai_terminology_expansion_member (scope_id text NOT NULL, valueset_url text NOT NULL, valueset_version text NOT NULL DEFAULT '', system_url text NOT NULL, system_version text NOT NULL DEFAULT '', code text NOT NULL, display text NOT NULL DEFAULT '', inactive boolean NOT NULL DEFAULT false, PRIMARY KEY(scope_id,valueset_url,valueset_version,system_url,system_version,code));
